<?php
namespace App\Domain\Missions\Services; use App\Domain\Missions\Models\{SeasonMission,SeasonMissionProgress}; use App\Domain\Rewards\Services\EntitlementService; use App\Models\User; use Illuminate\Support\Facades\{DB,Log};
class SeasonMissionService { public function __construct(private readonly EntitlementService $entitlements){} public function progressFromEvent(User $u,string $eventType,int $amount=1,array $metadata=[]):void{DB::transaction(function()use($u,$eventType,$amount,$metadata){SeasonMission::where('enabled',true)->where('progress_type',$eventType)->where(fn($q)=>$q->whereNull('starts_at')->orWhere('starts_at','<=',now()))->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>',now()))->get()->each(function($m)use($u,$amount,$metadata){$p=SeasonMissionProgress::firstOrCreate(['mission_id'=>$m->id,'user_id'=>$u->id],['metadata_json'=>[]]);$processed=$p->metadata_json['processed_event_ids']??[];$key=$metadata['dedupeKey']??null;if($key&&in_array($key,$processed,true))return;$value=min($m->target_value,$p->progress_value+max(0,$amount));if($key){$processed[]= $key;$processed=array_slice($processed,-100);} $p->update(['progress_value'=>$value,'progress_version'=>$p->progress_version+1,'metadata_json'=>array_merge($p->metadata_json??[],['processed_event_ids'=>$processed])]);if($value>=$m->target_value&&!$p->completed_at){$p->update(['completed_at'=>now()]);$this->claim($u,$m,$p);}});});} private function claim(User $u,SeasonMission $m,SeasonMissionProgress $p):void{if($p->reward_claimed_at)return;DB::table('player_progress')->updateOrInsert(['user_id'=>$u->id],['experience_points'=>DB::raw('COALESCE(experience_points, 0) + '.(int)$m->reward_xp),'level'=>1,'updated_at'=>now(),'created_at'=>now()]);if($m->reward_season_points)DB::table('season_participants')->where(['season_id'=>$m->season_id,'user_id'=>$u->id])->increment('mission_points',$m->reward_season_points);if($m->reward_cosmetic_key)$this->entitlements->grantOnce($u,'cosmetic',$m->reward_cosmetic_key,'mission',(string)$m->id);$p->update(['reward_claimed_at'=>now()]);} }
